grid=[r+[9]*(29-len(r)) for r in grid]
# Compare top band translated right 2 to lower band; get missing 8s and extras
for i in range(7):
    top=grid[i]; bot=grid[20+i]
    pred={c+2 for c,x in enumerate(top) if x==8 and c+2<29}
    actual={c for c,x in enumerate(bot) if x==8}
    print(i, 'missing lower', sorted(pred-actual),'extra lower', sorted(actual-pred))
